#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <input_string>\n", argv[0]);
        return 1;
    }

    char *input = argv[1];
    int length = strlen(input);
    char tape[32];
    int steps = 0;

    for (int i = 0; i < length; i++) {
        tape[i] = input[i];
    }

    int pos = 0;
    while (pos < length) {
        if (tape[pos] == '0') {
            tape[pos] = '1';
            pos++;
            steps++;
        } else if (tape[pos] == '1') {
            tape[pos] = '0';
            pos--;
            steps++;
        }

        if (pos < 0) {
            printf("OVERFLOW\n");
            return 1;
        }
    }

    printf("result=");
    for (int i = 0; i < length; i++) {
        printf("%c", tape[i]);
    }
    printf("\nsteps=%d\n", steps);

    return 0;
}
